package com.t1doo.aiyou

import java.nio.ByteBuffer
import java.nio.ByteOrder
import java.util.Base64

/** Generated neutral quadrants/solid pixels, synthetic GPS and comments; no user images. */
internal object JpegFixture {
    fun baseline(): ByteArray = Base64.getDecoder().decode("")
    fun progressive(): ByteArray = Base64.getDecoder().decode("")
    fun large(): ByteArray = Base64.getDecoder().decode("")

    fun segment(marker: Int, body: ByteArray): ByteArray = byteArrayOf(-1, marker.toByte(),
        ((body.size + 2) shr 8).toByte(), (body.size + 2).toByte()) + body
    fun exif(orientation: Int, little: Boolean = false, gps: Boolean = false): ByteArray {
        val tiff = ByteBuffer.allocate(if (gps) 140 else 26).order(if (little) ByteOrder.LITTLE_ENDIAN else ByteOrder.BIG_ENDIAN)
        tiff.put(if (little) 0x49.toByte() else 0x4d.toByte()); tiff.put(if (little) 0x49.toByte() else 0x4d.toByte())
        tiff.putShort(42); tiff.putInt(8); tiff.putShort(if (gps) 2 else 1)
        tiff.putShort(0x112); tiff.putShort(3); tiff.putInt(1); tiff.putShort(orientation.toShort()); tiff.putShort(0)
        if (gps) { tiff.putShort(0x8825.toShort()); tiff.putShort(4); tiff.putInt(1); tiff.putInt(38) }
        tiff.putInt(0)
        if (gps) {
            tiff.putShort(4)
            tiff.putShort(1); tiff.putShort(2); tiff.putInt(2); tiff.put(byteArrayOf(78,0,0,0))
            tiff.putShort(2); tiff.putShort(5); tiff.putInt(3); tiff.putInt(92)
            tiff.putShort(3); tiff.putShort(2); tiff.putInt(2); tiff.put(byteArrayOf(69,0,0,0))
            tiff.putShort(4); tiff.putShort(5); tiff.putInt(3); tiff.putInt(116)
            tiff.putInt(0)
            for (value in intArrayOf(45,30,0,60,10,0)) { tiff.putInt(value); tiff.putInt(1) }
        }
        return segment(0xe1, byteArrayOf(69,120,105,102,0,0) + tiff.array())
    }
    fun withMetadata(orientation: Int = 6, little: Boolean = false, progressive: Boolean = false): ByteArray {
        val image = if (progressive) progressive() else baseline()
        return image.copyOfRange(0,2) + exif(orientation,little,true) +
            segment(0xe1,"http://ns.adobe.com/xap/1.0/\u0000SYNTHETIC_XMP_POSITION".toByteArray()) +
            segment(0xed,"SYNTHETIC_IPTC_PERSON".toByteArray()) + segment(0xfe,"SYNTHETIC_COMMENT".toByteArray()) +
            segment(0xe4,"SYNTHETIC_UNKNOWN_APP".toByteArray()) + image.copyOfRange(2,image.size)
    }
    fun earlyEoi(): ByteArray {
        val bytes=baseline(); val sos=(2 until bytes.size-1).first { bytes[it]==(-1).toByte() && bytes[it+1]==0xda.toByte() }
        val header=((bytes[sos+2].toInt() and 255) shl 8) or (bytes[sos+3].toInt() and 255)
        return bytes.copyOf(sos+2+header+3) + byteArrayOf(-1,0xd9.toByte())
    }
}
